    /**
     * Tests getting all AuditPrograms.
     *
     * @return    Collection
     */
    public List<AuditProgram> testGetAll() throws Throwable {
    LOGGER.info( "AuditProgramTest:testGetAll() - Retrieving Collection of AuditPrograms:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AuditProgram : " );
    List<AuditProgram> collection  = null;

    try {
        // call the static get method on the AuditProgramService
        collection = service.getAllAuditProgram();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AuditProgram currEntity  = null;
            Iterator<AuditProgram> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAuditProgramId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

